class SvcDeskClient:
    """
    An idiomatic, dependency-free HTTP client wrapper for the Service Desk API
    using Python's built-in urllib library.
    """
    def __init__(self, base_url: str):
        self.base_url = base_url.rstrip("/")

    def request(self, method: str, path: str, body: dict = None, test_clock: str = None) -> tuple[int, dict]:
        url = f"{self.base_url}{path}"
        headers = {"Content-Type": "application/json"}
        if test_clock:
            headers["X-Test-Clock"] = test_clock

        data = json.dumps(body).encode("utf-8") if body is not None else None
        req = urllib.request.Request(url, data=data, headers=headers, method=method)

        try:
            with urllib.request.urlopen(req) as resp:
                status = resp.status
                resp_content = resp.read().decode("utf-8")
                resp_body = json.loads(resp_content) if resp_content else {}
                return status, resp_body
        except urllib.error.HTTPError as e:
            status = e.code
            try:
                resp_content = e.read().decode("utf-8")
                resp_body = json.loads(resp_content) if resp_content else {}
            except Exception:
                resp_body = {"error": {"code": "http_error", "message": e.reason}}
            return status, resp_body
        except Exception as e:
            # Handle connection or other network-level errors
            return 500, {"error": {"code": "connection_error", "message": str(e)}}


