def test_ticket_creation_validation_failures(client: SvcDeskClient):
    """
    R-20 / API.md §7: Validation failures should yield 400 or 422 with a JSON body
    carrying an 'error' object.
    """
    # Base valid body to manipulate
    base_body = {
        "title": "Valid Ticket Title",
        "description": "Valid description",
        "reporter": {"name": "John Doe", "email": "john@example.com", "vip": False},
        "impact": 2,
        "urgency": 2
    }

    # Helper to check validation fails
    def assert_validation_error(modified_body):
        status, body = client.request("POST", "/tickets", body=modified_body, test_clock="2026-10-14T10:00:00Z")
        assert status in (400, 422), f"Expected 400/422 for body: {modified_body}, got {status}"
        assert "error" in body, f"Expected 'error' object in body: {body}"

    # Title validation
    # 1. Missing title
    body_missing_title = base_body.copy()
    body_missing_title.pop("title")
    assert_validation_error(body_missing_title)

    # 2. Empty title
    body_empty_title = base_body.copy()
    body_empty_title["title"] = ""
    assert_validation_error(body_empty_title)

    # 3. Title too long (201 characters, limit is 200)
    body_long_title = base_body.copy()
    body_long_title["title"] = "A" * 201
    assert_validation_error(body_long_title)

    # Reporter validation
    # 4. Missing reporter name
    body_missing_rep_name = base_body.copy()
    body_missing_rep_name["reporter"] = {"email": "john@example.com"}
    assert_validation_error(body_missing_rep_name)

    # 5. Missing reporter block
    body_missing_rep = base_body.copy()
    body_missing_rep.pop("reporter")
    assert_validation_error(body_missing_rep)

    # Impact validation (allowed: 1, 2, 3)
    # 6. Impact too high
    body_invalid_impact_high = base_body.copy()
    body_invalid_impact_high["impact"] = 4
    assert_validation_error(body_invalid_impact_high)

    # 7. Impact too low
    body_invalid_impact_low = base_body.copy()
    body_invalid_impact_low["impact"] = 0
    assert_validation_error(body_invalid_impact_low)

    # 8. Impact string instead of integer
    body_string_impact = base_body.copy()
    body_string_impact["impact"] = "high"
    assert_validation_error(body_string_impact)

    # Urgency validation (allowed: 1, 2, 3)
    # 9. Urgency too high
    body_invalid_urgency_high = base_body.copy()
    body_invalid_urgency_high["urgency"] = 4
    assert_validation_error(body_invalid_urgency_high)

    # 10. Urgency too low
    body_invalid_urgency_low = base_body.copy()
    body_invalid_urgency_low["urgency"] = 0
    assert_validation_error(body_invalid_urgency_low)

    # 11. Urgency string instead of integer
    body_string_urgency = base_body.copy()
    body_string_urgency["urgency"] = "cosmetic"
    assert_validation_error(body_string_urgency)

    # Description validation
    # 12. Description too long (> 4000 chars)
    body_long_desc = base_body.copy()
    body_long_desc["description"] = "D" * 4001
    assert_validation_error(body_long_desc)


def test_ticket_ignores_read_only_and_unknown_fields(client: SvcDeskClient):
    """
    R-20 / API.md §2, §7: Server-owned and unknown fields in the request
    are silently ignored, never rejected.
    """
    payload = {
        "title": "Printer Jammed",
        "reporter": {"name": "Anna Nowak", "email": "anna@example.com", "vip": False},
        "impact": 3,
        "urgency": 2,
        # Server-owned fields to be ignored
        "id": "11111111-2222-3333-4444-555555555555",
        "priority": "P1",
        "state": "closed",
        "created_at": "2026-10-14T10:00:00Z",
        "sla": {"ack_due_at": "2026-10-14T10:15:00Z", "resolve_due_at": "2026-10-14T14:00:00Z"},
        # Unknown fields to be ignored
        "custom_field": "some_value",
        "another_ignored": 42
    }

    status, body = client.request("POST", "/tickets", body=payload, test_clock="2026-10-14T10:00:00Z")
    assert status == 201
    assert body["state"] == "new"  # Ignored payload state, defaults to new
    assert body["priority"] == "P4"  # Ignored P1 payload, computed based on 3/2 matrix
    assert body["id"] != "11111111-2222-3333-4444-555555555555"  # Generated by server
    assert "custom_field" not in body  # Unknown fields ignored and omitted in response


