def test_priority_matrix_under_c3_matrix(client: SvcDeskClient):
    """
    R-04, R-05, Conflict C3: Under C3 = matrix, priority is derived exclusively
    from the impact/urgency matrix. The 'reporter.vip' flag is stored but
    completely ignored for priority calculations.
    """
    matrix_cases = [
        # (impact, urgency, expected_priority)
        (1, 1, "P1"), (1, 2, "P2"), (1, 3, "P3"),
        (2, 1, "P2"), (2, 2, "P3"), (2, 3, "P4"),
        (3, 1, "P3"), (3, 2, "P4"), (3, 3, "P4")
    ]

    for impact, urgency, expected_prio in matrix_cases:
        # Check standard non-VIP reporter
        payload = {
            "title": f"Matrix ticket {impact}/{urgency}",
            "reporter": {"name": "Test User", "vip": False},
            "impact": impact,
            "urgency": urgency
        }
        status, body = client.request("POST", "/tickets", body=payload, test_clock="2026-10-14T10:00:00Z")
        assert status == 201
        assert body["priority"] == expected_prio, f"Non-VIP {impact}/{urgency} expected {expected_prio}, got {body['priority']}"

        # Conflict C3: VIP flag is IGNORED in calculation
        # Even with VIP=True, priority must strictly match the expected matrix priority (e.g. 3/3 VIP is P4, NOT P2).
        payload_vip = {
            "title": f"Matrix ticket VIP {impact}/{urgency}",
            "reporter": {"name": "VIP User", "vip": True},
            "impact": impact,
            "urgency": urgency
        }
        status, body_vip = client.request("POST", "/tickets", body=payload_vip, test_clock="2026-10-14T10:00:00Z")
        assert status == 201
        assert body_vip["reporter"]["vip"] is True
        assert body_vip["priority"] == expected_prio, (
            f"C3 Error: VIP flag was NOT ignored. VIP {impact}/{urgency} expected {expected_prio}, got {body_vip['priority']}"
        )


