def test_happy_path_state_transitions(client: SvcDeskClient):
    """
    R-07, API.md §6: Verifies the legal lifecycle transitions:
    new -> acknowledged -> in_progress -> resolved -> closed
    Each action sets its respective event timestamp.
    """
    # Create new ticket
    payload = {
        "title": "State machine ticket",
        "reporter": {"name": "Agent Smith"},
        "impact": 2,
        "urgency": 2
    }
    status, ticket = client.request("POST", "/tickets", body=payload, test_clock="2026-10-14T10:00:00Z")
    assert status == 201
    assert ticket["state"] == "new"
    assert ticket["created_at"] == "2026-10-14T10:00:00Z"
    assert ticket["acknowledged_at"] is None
    assert ticket["resolved_at"] is None
    assert ticket["closed_at"] is None

    ticket_id = ticket["id"]

    # 1. Acknowledge: new -> acknowledged
    status, ticket = client.request("POST", f"/tickets/{ticket_id}/ack", test_clock="2026-10-14T10:05:00Z")
    assert status == 200
    assert ticket["state"] == "acknowledged"
    assert ticket["acknowledged_at"] == "2026-10-14T10:05:00Z"

    # 2. Start: acknowledged -> in_progress
    status, ticket = client.request("POST", f"/tickets/{ticket_id}/start", test_clock="2026-10-14T10:10:00Z")
    assert status == 200
    assert ticket["state"] == "in_progress"

    # 3. Resolve: in_progress -> resolved
    status, ticket = client.request("POST", f"/tickets/{ticket_id}/resolve", test_clock="2026-10-14T10:30:00Z")
    assert status == 200
    assert ticket["state"] == "resolved"
    assert ticket["resolved_at"] == "2026-10-14T10:30:00Z"

    # 4. Close: resolved -> closed
    status, ticket = client.request("POST", f"/tickets/{ticket_id}/close", test_clock="2026-10-14T10:45:00Z")
    assert status == 200
    assert ticket["state"] == "closed"
    assert ticket["closed_at"] == "2026-10-14T10:45:00Z"


def test_illegal_state_transitions_yield_409(client: SvcDeskClient):
    """
    R-08, API.md §6: Any illegal transitions return 409 Conflict.
    Closed tickets are immutable (R-09).
    """
    payload = {
        "title": "Strict State transitions",
        "reporter": {"name": "Agent Smith"},
        "impact": 2,
        "urgency": 2
    }
    status, ticket = client.request("POST", "/tickets", body=payload, test_clock="2026-10-14T10:00:00Z")
    assert status == 201
    ticket_id = ticket["id"]

    # Attempt to skip acknowledge (new -> start)
    status, body = client.request("POST", f"/tickets/{ticket_id}/start", test_clock="2026-10-14T10:05:00Z")
    assert status == 409
    assert "error" in body

    # Attempt to resolve from new
    status, body = client.request("POST", f"/tickets/{ticket_id}/resolve", test_clock="2026-10-14T10:05:00Z")
    assert status == 409

    # Attempt to close from new
    status, body = client.request("POST", f"/tickets/{ticket_id}/close", test_clock="2026-10-14T10:05:00Z")
    assert status == 409

    # Advance legal to acknowledged
    status, _ = client.request("POST", f"/tickets/{ticket_id}/ack", test_clock="2026-10-14T10:05:00Z")
    assert status == 200

    # Attempt to resolve from acknowledged
    status, body = client.request("POST", f"/tickets/{ticket_id}/resolve", test_clock="2026-10-14T10:10:00Z")
    assert status == 409

    # Advance to in_progress
    status, _ = client.request("POST", f"/tickets/{ticket_id}/start", test_clock="2026-10-14T10:10:00Z")
    assert status == 200

    # Attempt to close from in_progress
    status, body = client.request("POST", f"/tickets/{ticket_id}/close", test_clock="2026-10-14T10:15:00Z")
    assert status == 409

    # Advance to resolved
    status, _ = client.request("POST", f"/tickets/{ticket_id}/resolve", test_clock="2026-10-14T10:15:00Z")
    assert status == 200

    # Attempt to acknowledge or start from resolved
    status, body = client.request("POST", f"/tickets/{ticket_id}/ack", test_clock="2026-10-14T10:20:00Z")
    assert status == 409
    status, body = client.request("POST", f"/tickets/{ticket_id}/start", test_clock="2026-10-14T10:20:00Z")
    assert status == 409

    # Advance to closed
    status, _ = client.request("POST", f"/tickets/{ticket_id}/close", test_clock="2026-10-14T10:25:00Z")
    assert status == 200

    # Immutable closed ticket checks (R-09): Attempt any action other than reopen
    status, body = client.request("POST", f"/tickets/{ticket_id}/ack", test_clock="2026-10-14T10:30:00Z")
    assert status == 409
    status, body = client.request("POST", f"/tickets/{ticket_id}/start", test_clock="2026-10-14T10:30:00Z")
    assert status == 409
    status, body = client.request("POST", f"/tickets/{ticket_id}/resolve", test_clock="2026-10-14T10:30:00Z")
    assert status == 409
    status, body = client.request("POST", f"/tickets/{ticket_id}/close", test_clock="2026-10-14T10:30:00Z")
    assert status == 409


