def test_reopen_window_under_c2_reopen(client: SvcDeskClient):
    """
    R-10, R-11, Conflict C2: Under C2 = reopen:
    - Reopen is allowed from 'resolved' and from 'closed' within 7 days.
    - Reopening returns the ticket to 'in_progress', and clears resolved_at and closed_at.
    - Outside the 7-day window, reopen is refused with 409 Conflict.
    """
    # Create ticket
    payload = {
        "title": "Reopen test ticket",
        "reporter": {"name": "Jane User"},
        "impact": 2,
        "urgency": 2
    }
    status, ticket = client.request("POST", "/tickets", body=payload, test_clock="2026-10-14T10:00:00Z")
    assert status == 201
    ticket_id = ticket["id"]

    # Transition to resolved at 2026-10-14T10:30:00Z
    client.request("POST", f"/tickets/{ticket_id}/ack", test_clock="2026-10-14T10:05:00Z")
    client.request("POST", f"/tickets/{ticket_id}/start", test_clock="2026-10-14T10:10:00Z")
    status, ticket = client.request("POST", f"/tickets/{ticket_id}/resolve", test_clock="2026-10-14T10:30:00Z")
    assert status == 200
    assert ticket["state"] == "resolved"
    assert ticket["resolved_at"] == "2026-10-14T10:30:00Z"

    # CASE A: Reopen from RESOLVED exactly 7 days later (2026-10-21T10:30:00Z) - should succeed
    status, ticket_reopened = client.request("POST", f"/tickets/{ticket_id}/reopen", test_clock="2026-10-21T10:30:00Z")
    assert status == 200, f"Expected reopen success, got {status}"
    assert ticket_reopened["state"] == "in_progress"
    assert ticket_reopened["resolved_at"] is None
    assert ticket_reopened["closed_at"] is None

    # Resolve again at 2026-10-21T11:00:00Z
    status, ticket = client.request("POST", f"/tickets/{ticket_id}/resolve", test_clock="2026-10-21T11:00:00Z")
    assert status == 200
    assert ticket["resolved_at"] == "2026-10-21T11:00:00Z"

    # CASE B: Reopen from RESOLVED 7 days + 1 second later (2026-10-28T11:00:01Z) - should fail
    status, error_body = client.request("POST", f"/tickets/{ticket_id}/reopen", test_clock="2026-10-28T11:00:01Z")
    assert status == 409
    assert "error" in error_body

    # Close ticket to test reopening from closed state
    status, ticket = client.request("POST", f"/tickets/{ticket_id}/close", test_clock="2026-10-28T11:15:00Z")
    assert status == 200
    assert ticket["state"] == "closed"
    assert ticket["closed_at"] == "2026-10-28T11:15:00Z"

    # CASE C: Under C2 = reopen, reopen is allowed from CLOSED. Reopen within 7 days from close (2026-11-04T11:15:00Z)
    status, ticket_reopened_closed = client.request("POST", f"/tickets/{ticket_id}/reopen", test_clock="2026-11-04T11:15:00Z")
    assert status == 200, f"C2 Error: expected reopening from closed to be allowed, got {status}"
    assert ticket_reopened_closed["state"] == "in_progress"
    assert ticket_reopened_closed["resolved_at"] is None
    assert ticket_reopened_closed["closed_at"] is None

    # Close again at 2026-11-04T12:00:00Z (Must resolve -> close)
    client.request("POST", f"/tickets/{ticket_id}/resolve", test_clock="2026-11-04T11:30:00Z")
    client.request("POST", f"/tickets/{ticket_id}/close", test_clock="2026-11-04T12:00:00Z")

    # CASE D: Reopen from CLOSED 7 days + 1 second later (2026-11-11T12:00:01Z) - should fail
    status, error_body = client.request("POST", f"/tickets/{ticket_id}/reopen", test_clock="2026-11-11T12:00:01Z")
    assert status == 409
    assert "error" in error_body


