@pytest.mark.parametrize("vector_id, priority, created_at, expected_ack, expected_resolve", [
    # T1: P1, created Wednesday 12:00 CEST. P1 is wall-clock under C1 = wallclock.
    ("T1", "P1", "2026-10-14T10:00:00Z", "2026-10-14T10:15:00Z", "2026-10-14T14:00:00Z"),
    # T2: P3, created Friday 15:30 CEST. P3 is always business-hours.
    ("T2", "P3", "2026-10-16T13:30:00Z", "2026-10-19T09:30:00Z", "2026-10-21T13:30:00Z"),
    # T3: P1, created Friday 17:00 CEST. P1 is wall-clock.
    ("T3", "P1", "2026-10-16T15:00:00Z", "2026-10-16T15:15:00Z", "2026-10-16T19:00:00Z"),
    # T4: P2, created Saturday 12:00 CEST. P2 is always business-hours. (Monday 16:00 local = 14:00Z)
    ("T4", "P2", "2026-10-17T10:00:00Z", "2026-10-19T07:00:00Z", "2026-10-19T14:00:00Z"),
    # T5: P4, created Thursday 15:30 CET (Jan). P4 is always business-hours. (Wednesday 15:30 local = 14:30Z)
    ("T5", "P4", "2027-01-14T14:30:00Z", "2027-01-15T14:30:00Z", "2027-01-27T14:30:00Z"),
    # T6: P1, created Friday 16:50 CET. P1 is wall-clock.
    ("T6", "P1", "2027-01-15T15:50:00Z", "2027-01-15T16:05:00Z", "2027-01-15T19:50:00Z"),
    # T7: P2, created Wednesday 12:00 CEST. P2 is always business-hours. (Thursday 12:00 local = 10:00Z)
    ("T7", "P2", "2026-10-14T10:00:00Z", "2026-10-14T11:00:00Z", "2026-10-15T10:00:00Z"),
    # T8: P3, created Friday 15:00 CEST (DST ends Sun). P3 is always business-hours. (Wednesday 15:00 CET = 14:00Z)
    ("T8", "P3", "2026-10-23T13:00:00Z", "2026-10-26T10:00:00Z", "2026-10-28T14:00:00Z")
])
def test_sla_vectors_under_c1_wallclock(client: SvcDeskClient, vector_id, priority, created_at, expected_ack, expected_resolve):
    """
    R-12, R-13, R-14, Conflict C1: Under C1 = wallclock:
    - P1 SLA targets are wall-clock (24/7).
    - P2, P3, P4 SLA targets count only business hours (Mon-Fri 08:00-16:00 Europe/Warsaw).
    Verifies that the API returns the exact SLA due dates corresponding to the T1..T8 test vectors.
    """
    # Map priority to impact/urgency to produce that priority under matrix
    # P1 -> 1, 1
    # P2 -> 2, 1
    # P3 -> 1, 3
    # P4 -> 2, 3
    prio_map = {
        "P1": (1, 1),
        "P2": (2, 1),
        "P3": (1, 3),
        "P4": (2, 3)
    }
    impact, urgency = prio_map[priority]

    payload = {
        "title": f"SLA Vector {vector_id}",
        "reporter": {"name": "Test Runner"},
        "impact": impact,
        "urgency": urgency
    }

    status, body = client.request("POST", "/tickets", body=payload, test_clock=created_at)
    assert status == 201, f"Failed to create ticket for vector {vector_id}"
    assert body["priority"] == priority

    # Verify both due instants inside the created ticket's SLA block match the vector
    sla = body.get("sla", {})
    assert sla.get("ack_due_at") == expected_ack, f"{vector_id}: ack_due_at mismatch. Expected {expected_ack}, got {sla.get('ack_due_at')}"
    assert sla.get("resolve_due_at") == expected_resolve, f"{vector_id}: resolve_due_at mismatch. Expected {expected_resolve}, got {sla.get('resolve_due_at')}"


