# 7. SLA Status, Breach, and Pause (R-15, R-16, API.md §5)
# ==============================================================================

def test_sla_breach_and_pause_behavior(client: SvcDeskClient):
    """
    R-15, R-16, API.md §5: Verifies that GET /tickets/{id}/sla returns the correct:
    - ack_breached: true if now > ack_due_at and not ack'd, or ack'd > ack_due_at
    - resolve_breached: true if now > resolve_due_at and not resolved, or resolved > resolve_due_at
    - paused: true if not resolved/closed, business-clock target, and now is outside business hours
    """
    # Create T4 (P2) ticket (business clock): Saturday 2026-10-17T10:00:00Z
    # ack_due_at = 2026-10-19T07:00:00Z
    # resolve_due_at = 2026-10-19T14:00:00Z
    payload = {
        "title": "Breach & Pause check",
        "reporter": {"name": "SLA Inspector"},
        "impact": 2,
        "urgency": 1
    }
    status, ticket = client.request("POST", "/tickets", body=payload, test_clock="2026-10-17T10:00:00Z")
    assert status == 201
    assert ticket["priority"] == "P2"
    ticket_id = ticket["id"]

    # --- Case 1: Check SLA on Saturday 12:00Z (outside business hours, not acknowledged)
    status, sla = client.request("GET", f"/tickets/{ticket_id}/sla", test_clock="2026-10-17T12:00:00Z")
    assert status == 200
    assert sla["ack_breached"] is False
    assert sla["resolve_breached"] is False
    assert sla["paused"] is True  # Active, business-hours ticket checked outside business hours

    # --- Case 2: Check SLA exactly at the due instant: Monday 2026-10-19T07:00:00Z (No breach yet)
    status, sla = client.request("GET", f"/tickets/{ticket_id}/sla", test_clock="2026-10-19T07:00:00Z")
    assert status == 200
    assert sla["ack_breached"] is False
    assert sla["paused"] is False  # Monday 09:00 CEST is inside business hours

    # --- Case 3: Check SLA after due instant: Monday 2026-10-19T07:00:01Z (Breach occurs)
    status, sla = client.request("GET", f"/tickets/{ticket_id}/sla", test_clock="2026-10-19T07:00:01Z")
    assert status == 200
    assert sla["ack_breached"] is True

    # --- Case 4: Acknowledge late (at 2026-10-19T07:05:00Z) and verify breach persists
    client.request("POST", f"/tickets/{ticket_id}/ack", test_clock="2026-10-19T07:05:00Z")
    status, sla = client.request("GET", f"/tickets/{ticket_id}/sla", test_clock="2026-10-19T08:00:00Z")
    assert status == 200
    assert sla["ack_breached"] is True  # Late acknowledgement = permanently breached

    # --- Case 5: Verify wall-clock tickets (P1) are NEVER paused under C1 = wallclock
    # Create T1 (P1) ticket at Wednesday 2026-10-14T10:00:00Z
    payload_p1 = {
        "title": "P1 Wallclock pause check",
        "reporter": {"name": "SLA Inspector"},
        "impact": 1,
        "urgency": 1
    }
    status, ticket_p1 = client.request("POST", "/tickets", body=payload_p1, test_clock="2026-10-14T10:00:00Z")
    assert status == 201
    assert ticket_p1["priority"] == "P1"
    ticket_p1_id = ticket_p1["id"]

    # Check SLA at Wednesday 18:00Z (20:00 CEST, outside business hours)
    status, sla_p1 = client.request("GET", f"/tickets/{ticket_p1_id}/sla", test_clock="2026-10-14T18:00:00Z")
    assert status == 200
    assert sla_p1["paused"] is False  # P1 uses wallclock, so it is never paused


# ==============================================================================
# 8. Listing and Filtering Tests (R-19, API.md §1)
# ==============================================================================

def test_ticket_listing_and_filtering(client: SvcDeskClient):
    """
    R-19, API.md §1: GET /tickets lists all tickets.
    Supports optional exact-match filters for 'state' and 'priority'.
    """
    # 1. Clear state or work with current tickets. Let's create two unique tickets with specific states and priorities
    p1_title = f"Filter P1 - {uuid.uuid4()}"
    p3_title = f"Filter P3 - {uuid.uuid4()}"

    # Create first ticket (P1, state starts as 'new')
    status, t1 = client.request("POST", "/tickets", body={
        "title": p1_title,
        "reporter": {"name": "Filter tester"},
        "impact": 1,
        "urgency": 1
    }, test_clock="2026-10-14T10:00:00Z")
    assert status == 201
    t1_id = t1["id"]

    # Create second ticket (P3, transition to 'acknowledged')
    status, t2 = client.request("POST", "/tickets", body={
        "title": p3_title,
        "reporter": {"name": "Filter tester"},
        "impact": 1,
        "urgency": 3
    }, test_clock="2026-10-14T10:00:00Z")
    assert status == 201
    t2_id = t2["id"]

    # Transition second ticket to 'acknowledged'
    client.request("POST", f"/tickets/{t2_id}/ack", test_clock="2026-10-14T10:05:00Z")

    # Fetch full list and verify both are returned
    status, all_tickets = client.request("GET", "/tickets")
    assert status == 200
    assert isinstance(all_tickets, list)
    titles = [t["title"] for t in all_tickets]
    assert p1_title in titles
    assert p3_title in titles

    # Filter by state: state=acknowledged
    status, ack_tickets = client.request("GET", "/tickets?state=acknowledged")
    assert status == 200
    for t in ack_tickets:
        assert t["state"] == "acknowledged"
    ack_titles = [t["title"] for t in ack_tickets]
    assert p3_title in ack_titles
    assert p1_title not in ack_titles

    # Filter by priority: priority=P1
    status, p1_tickets = client.request("GET", "/tickets?priority=P1")
    assert status == 200
    for t in p1_tickets:
        assert t["priority"] == "P1"
    p1_titles = [t["title"] for t in p1_tickets]
    assert p1_title in p1_titles
    assert p3_title not in p1_titles

    # Filter by both state and priority: state=new&priority=P1
    status, combined_tickets = client.request("GET", "/tickets?state=new&priority=P1")
    assert status == 200
    for t in combined_tickets:
        assert t["state"] == "new"
        assert t["priority"] == "P1"
    combined_titles = [t["title"] for t in combined_tickets]
    assert p1_title in combined_titles
    assert p3_title not in combined_titles
